@startuml structural
' Enumerations
enum OrderStatus {
    submitted
    pending
    filled
    shipped
    closed
}
enum InvoiceStatus {
    issued
    paid
}
enum PaymentStatus {
    pending
    completed
    failed
}
enum PaymentMethod {
    bank
    card
    cash
}

' Domain classes
class Customer {
    +String name
    +String address
    +String phoneNumber
}
class BankAccount {
    +String accountNumber
    +String routingNumber
}
class Product {
    +String name
    +String description
    +Decimal price
    +String imageUrl
}
class Order {
    +Date orderDate
    +Decimal totalAmount
    +OrderStatus status
    +PaymentMethod paymentMethod
}
class OrderItem {
    +int quantity
    +Decimal unitPrice
}
class Invoice {
    +Date date
    +Decimal amount
    +InvoiceStatus status
    +PaymentMethod paymentMethod
}
class Payment {
    +Date date
    +Decimal amount
    +PaymentStatus status
    +PaymentMethod paymentMethod
}

' Relationships
Customer "1" o-- "0..1" BankAccount : has
Customer "1" o-- "0..*" Order : places
Order "1" o-- "0..*" OrderItem : contains
OrderItem "1" --> "1" Product : refers
Order "1" o-- "0..1" Invoice : billed_by
Invoice "1" o-- "0..*" Payment : records

@enduml



**File: `behavioral.puml`**

@startuml behavioral
|Customer|
start
:Browse Products;
partition SubmitOrder {
    :Create Order;
    if (Customer known?) then (yes)
        if (At least one OrderItem?) then (yes)
            if (All Products exist?) then (yes)
                :Compute total;
                :Set status to submitted;
                :Store Order;
                note right: Order [submitted]
            else (no)
                :Reject - unknown product;
                stop
            endif
        else (no)
            :Reject - no items;
            stop
        endif
    else (no)
        :Reject - unknown customer;
        stop
    endif
}
|OrderStaff|
partition ReceiveOrder {
    if (Order status == submitted) then (yes)
        :Set status to pending;
        note right: Order [pending]
    else (no)
        :Reject receive;
    endif
}
partition FillOrder {
    if (Order status == pending) then (yes)
        :Set status to filled;
        note right: Order [filled]
    else (no)
        :Reject fill;
    endif
}
partition ShipOrder {
    if (Order status == filled) then (yes)
        :Set status to shipped;
        note right: Order [shipped]
    else (no)
        :Reject ship;
    endif
}
|Accountant|
partition Invoice {
    if (Order status in (filled, shipped) && !Order.Invoice) then (yes)
        :Create Invoice (status issued);
        note right: Invoice [issued]
    else (no)
        :Reject invoice creation;
    endif
}
partition Payment {
    if (Invoice status == issued) then (yes)
        :Create Payment (status pending);
        note right: Payment [pending]
    else (no)
        :Reject payment;
    endif
}
partition ConfirmPayment {
    if (Payment status == pending) then (yes)
        :Set Payment status to completed;
        :Set Invoice status to paid;
        note right: Payment [completed]\nInvoice [paid]
    else (no)
        :Reject confirm;
    endif
}
partition RejectPayment {
    if (Payment status == pending) then (yes)
        :Set Payment status to failed;
        note right: Payment [failed]
    else (no)
        :Reject reject;
    endif
}
|OrderStaff|
partition CloseOrder {
    if (Order status == shipped && Invoice status == paid) then (yes)
        :Set Order status to closed;
        note right: Order [closed]
    else (no)
        :Reject close;
    endif
}
stop
@enduml



