' Enumerations
enum OrderStatus {
    submitted
    pending
    filled
    shipped
    closed
}
enum InvoiceStatus {
    issued
    paid
}
enum PaymentStatus {
    pending
    completed
    failed
}
enum PaymentMethod {
    bank
    card
    cash
}

' Domain classes
class Customer {
    +String name
    +String address
    +String phoneNumber
}
class BankAccount {
    +String accountNumber
    +String routingNumber
}
class Product {
    +String name
    +String description
    +Decimal price
    +String imageUrl
}
class Order {
    +Date orderDate
    +Decimal totalAmount
    +OrderStatus status
    +PaymentMethod paymentMethod
}
class OrderItem {
    +int quantity
    +Decimal unitPrice
}
class Invoice {
    +Date date
    +Decimal amount
    +InvoiceStatus status
    +PaymentMethod paymentMethod
}
class Payment {
    +Date date
    +Decimal amount
    +PaymentStatus status
    +PaymentMethod paymentMethod
}

' Relationships
Customer "1" o-- "0..1" BankAccount : has
Customer "1" o-- "0..*" Order : places
Order "1" o-- "0..*" OrderItem : contains
OrderItem "1" --> "1" Product : refers
Order "1" o-- "0..1" Invoice : billed_by
Invoice "1" o-- "0..*" Payment : records

