{"content":"@startuml structural

' Enumerations
enum OrderStatus {
    submitted
    pending
    filled
    shipped
    closed
}
enum InvoiceStatus {
    issued
    paid
}
enum PaymentStatus {
    pending
    completed
    failed
}
enum PaymentMethod {
    bank
    card
    cash
}

' Domain classes
class Customer {
    +name: String
    +address: String
    +phone: String
    +bankAccount: BankAccount [0..1]
}
class BankAccount {
    +accountNumber: String
}
class Product {
    +name: String
    +description: String
    +price: Decimal
    +imageUrl: String
}
class Order {
    +orderDate: Date
    +totalAmount: Decimal
    +status: OrderStatus
    +paymentMethod: PaymentMethod
}
class OrderItem {
    +quantity: Integer
    +unitPrice: Decimal
}
class Invoice {
    +date: Date
    +amount: Decimal
    +status: InvoiceStatus
    +paymentMethod: PaymentMethod
}
class Payment {
    +date: Date
    +amount: Decimal
    +status: PaymentStatus
    +paymentMethod: PaymentMethod
}

' Relationships
Customer "1" --> "0..*" Order : places >
Order "1" *-- "0..*" OrderItem : contains >
OrderItem "1" --> "1" Product : refers to >
Order "0..1" --> "1" Invoice : has >
Invoice "1" *-- "0..*" Payment : records >

@enduml","path":"structural.puml"}

{"content":"@startuml behavioral

' Swimlanes
|Customer|
start
:RegisterCustomer;
note right: US-01
:BrowseProducts;
note right: US-03
:SubmitOrder;
note right: US-04
partition OrderProcessing {
    |OrderStaff|
    :ReceiveOrder;
    note right: US-05
    :MarkOrderPending;
    note right: US-05
    :FillOrder;
    note right: US-06
    fork
        :ShipOrder;
        note right: US-07
    fork again
        :RaiseInvoice;
        note right: US-10
    end fork
    :CloseOrder;
    note right: US-09
}
|Accountant|
:RaiseInvoice;
note right: US-10
:SubmitPayment;
note right: US-11
:ConfirmPayment;
note right: US-12
:RejectPayment;
note right: US-13
stop

' Object nodes showing status changes
:Order [submitted];
:Order [pending];
:Order [filled];
:Order [shipped];
:Order [closed];
:Invoice [issued];
:Invoice [paid];
:Payment [pending];
:Payment [completed];
:Payment [failed];

@enduml","path":"behavioral.puml"}

